    ('د ګلابي بولوورم پیژندل او زیان څه دی؟', 'دا کوکون ته ننوځي او دانه خوري او پنبه خرابوي. دا د "بنډ فول" (د ګلاب ګل) لخوا پیژندل شوی.', 'د آفتونو مدیریت'),
    ("د ګلابي سنډي په کنټرول کې د 'سیکس فیرومون جال' رول څه دی؟", 'دا جالونه نارینه کیټرپلرونه جذبوي او د دوی د تکثیر مخه نیسي او کروندګر ته د آفت د شدت احساس ورکوي.', 'د آفتونو مدیریت'),
    ('د اردو ورم حمله کله شدیده ده؟', 'دا فنګس د شپې په پاڼو او ډډونو برید کوي او کولی شي ټول فصل په ډیر لنډ وخت کې وژني. دا برید د مونسون بارانونو وروسته ډیر ځله کیږي.', 'د آفتونو مدیریت'),
    ('ولې د میلیبګ کنټرول ستونزمن دی؟', 'د ملیبګ بدن یو سپین مومی پوښ لري چې زهر یې بدن ته د ننوتلو مخه نیسي ، نو د دې لپاره ځانګړي سپرې او صابون محلول کارول کیږي.', 'د آفتونو مدیریت'),
    ('د پنبې د پاڼو curl ویروس (CLCuV) نښې څه دي؟', 'د دې ویروس له امله، د نبات پاڼي پورته پورته کیږي، رګونه موټی کیږي او د نبات لوړوالی ودریږي.', 'د ناروغیو مدیریت'),
    ('د پنبې د راټولولو مناسب وخت کوم دی؟', 'کله چې په کرونده کې د 50 څخه تر 60 سلنې پورې ونې په بشپړه توګه وده وکړي، لومړی باید غوره شي. معماري باید تل له لمر لوېدو وروسته تر سره شي کله چې اوښ وچ شي.', 'معماري او ښاخ کول'),
    ('د لنده پنبه ګینګ څنګه د بټ کیفیت اغیزه کوي؟', 'که پنبه لوند واخيستل شي، ژيړ شي، پنبه په ټوټو بدلېږي او په بازار کې ډېر لږ ارزښت لري.', 'معماري او ښاخ کول'),
    ('ولې د معمارۍ پر مهال د پولیتین یا پلاستیکي کڅوړو کارول منع دي؟', 'پلاستيکي فایبرونه په پنبه کې ځای پرځای کیږي او د ټوکر ملونو ماشینونو ته زیان رسوي، په دې توګه د پنبې نړیوال کیفیت کموي او صادرات اغیزمنوي.', 'معماري او ښاخ کول'),
    ('د پنبې تخم او پنبې تخم ترمنځ توپیر څه دی؟', 'د تخم او پنبې مخلوط چې له کروندې څخه ترلاسه کیږي د فاټي په نوم یادیږي. د جنین کولو پروسې وروسته، پنبه جلا کیږي او تخم د بنولا په نوم یادیږي.', 'اقتصاد او بازارموندنه'),
    ('په هر جریبه کې د پنبې اوسط حاصل باید څومره وي؟', 'په پاکستان کې پرمختللی کروندګر د ښه مدیریت سره په هر جریبه کې له 30 څخه تر 40 منه حاصلات ترلاسه کوي، په داسې حال کې چې ملي اوسط د 15 څخه تر 20 منونو پورې دی.', 'اقتصاد او بازارموندنه'),
    ('د کروندګر لپاره د پنبې لرګي (لښتې) کارول څه دي؟', 'د پنبې لرګي په کلیو کې د سونګ په توګه کارول کیږي، مګر دوی باید د جنوري په میاشت کې لیرې شي ترڅو ګلابي سنډی له منځه یوسي.', 'معماري او ښاخ کول'),
    ('د جنریټ آؤټ ټرن (GOT) څخه څه مراد دی؟', 'دا پدې مانا ده چې د 100 کیلو ګرامه پنبې څخه څومره کیلو پاکه پنبه ترلاسه کیږي. معمولا دا کچه له 33 څخه تر 38 سلنې پورې وي.', 'اقتصاد او بازارموندنه'),
    ('په پاکستان کې د جوارو د کښت لپاره کوم ډول خاوره ډیره مناسبه ده؟', 'حاصل ورکونکې، ژورې او ښه وچې شوې لومې خاورې د جوارو لپاره غوره دي. دا نبات نشي کولی د اوبو ډکول یا شدید مالګینتوب برداشت کړي.', 'د ځمکې چمتو کول'),
    ('د جوارو د کرلو لپاره ځمکه باید څنګه چمتو شي؟', 'ځمکه باید لومړی د ژورو جوارو په واسطه وکرل شي، بیا وروسته له 2 څخه تر 3 ځله عمومي کوره وشي ترڅو خاوره نرمه، بډایه او له زیان رسوونکو واښو څخه پاکه شي.', 'د ځمکې چمتو کول'),
    ('د جوارو د کرلو غوره لاره څه ده؟', 'دا تل سپارښتنه کیږي چې جوار په پورته بسترونو کې وکرئ. دا طریقه اوبه خوندي کوي، د تخم د خرابیدو مخه نیسي او د نبات ډډ د مستقیم اوبو څخه ساتي.', 'د ځمکې چمتو کول'),
    ('د هایبرډ جوارو لپاره د قطار څخه تر قطار فاصله باید څه وي؟', 'د کښت کولو په صورت کې، د قطار څخه قطار فاصله دوه نیم فوټ (75 سانتي متره) ساتل کیږي.', 'د ځمکې چمتو کول'),
    ('د جوارو بوټي باید څومره فاصله ولري؟', 'د نباتاتو تر مینځ فاصله باید له 7 څخه تر 9 انچو پورې وکارول شي ترڅو د نبات بشپړ شمیر وساتل شي ترڅو په هر جریبه کې له 28,000 څخه تر 32,000 پورې نباتات تولید شي.', 'د ځمکې چمتو کول'),
    ('ولې د جوارو د تخم ټوکیدنه اغیزمن کیږي؟', 'د تخم ډیر ژور کرل، په وچه خاوره کې کرل، د زاړه یا عیب لرونکي تخم کارول، یا د باران وروسته د خاورې ترکیب کولی شي د ټوکیدنې مخه ونیسي.', 'د ځمکې چمتو کول'),
    ('د جوارو تخم باید څومره ژور کرل شي؟', 'تخم باید په لنده خاوره کې له یو نیم څخه تر دوه انچو پورې ژور وکرل شي.', 'د ځمکې چمتو کول'),
    ('آیا جوار په وچه خاوره کې د کرلو وروسته اوبه کیدی شي؟', 'هو، د وچ کرلو وروسته سمدستي اوبه ورکول کیدی شي، مګر په پام کې ونیسئ چې اوبه په څنډو باندې تیر نشي یا تخم به خراب شي.', 'د ځمکې چمتو کول'),
    ('په هر جریبه کې د جوارو د تخم اندازه باید څومره وي؟', 'له 8 څخه تر 10 کیلو ګرامه په هر جریبه کې د غلې دانې لپاره کارول کیږي، پداسې حال کې چې د 30 څخه تر 35 کیلو ګرامه تخم د وښو یا سلیج لپاره کارول کیږي.', 'تخمونه او ډولونه'),
    ('ولې په پاکستان کې د دودیزو ډولونو په پرتله هایبرډ جوار غوره کیږي؟', 'هایبرډ جوار د دودیزو ډولونو په پرتله له 2 څخه تر 3 ځله ډیر حاصل ورکوي، ورته لوړوالی لري او د سرې لپاره ښه زغم لري.', 'تخمونه او ډولونه'),
    ('په پاکستان کې د هایبرډ جوارو مشهور ډولونه کوم دي؟', 'مشهور ډولونه شامل دي Pioneer (د مثال په توګه 30Y87)، DeKalb (DK-6789)، Sengenta (NK-8441) او محلي هایبرډونه (YH-1898).', 'تخمونه او ډولونه'),
    ('ایا کروندګر کولی شي د راتلونکي کال لپاره د جوارو هایبرډ تخمونه خوندي کړي؟', 'نه، د هایبرډ بوټو څخه د تخمونو بیا کرل په سخته توګه حاصلات کموي او بوټي یو شان نه پاتې کیږي.', 'تخمونه او ډولونه'),
    ('ولې د جوارو تخم مسموم کول مهم دي؟', 'تخم ته د حشراتو وژونکو او فنګس وژونکو (لکه امیډا کلوپارډ) کارول نبات د لومړیو آفتونو (د مچانو ډزې) او ناروغیو څخه ساتي.', 'تخمونه او ډولونه'),
    ('د پاکستان کوم ولایت د جوارو په تولید کې مخکښ دی؟', 'پنجاب د جوارو لومړی تولیدوونکی هیواد دی چې د هیواد د ټول تولید ۸۰ سلنه برخه جوړوي.', 'ولایت: پنجاب'),
    ('د پنجاب کومې ولسوالۍ دي چیرې چې جوار ډیر کرل کیږي؟', "ساهیوال، اوکاڑه، پاکپتن، قصور، وهاري او فیصل آباد د پنجاب د 'میز بیلټ' (د جوارو د قوي مرکزونو) په توګه پیژندل کیږي.", 'ولایت: پنجاب'),
    ('په پنجاب کې څومره جوار کرل کېږي؟', 'په پنجاب کې دوه اصلي فصلونه کرل کیږي: بهاریه جوار (فبروري-مارچ) او موسمي یا خریف جوار (جولای-اګست).', 'ولایت: پنجاب'),
    ('ولې د پسرلي جوار ډیر ګټور ګڼل کیږي؟', 'د بهاریا جوار د پخیدو وخت او د لمر ډیر رڼا ترلاسه کوي، چې په هر جریبه کې یې حاصل له 100 څخه تر 120 منونو پورې لوړیږي.', 'ولایت: پنجاب'),
    ('د خریف (موسمی) جوارو عمده ننګونې کومې دي؟', 'د کرنې په وخت کې سخته تودوخه، د بارانونو له امله د اوبو بندیدل او د آفتونو ډیر برید لکه د "زوال آرمی ورم" لوی ننګونې دي.', 'ولایت: پنجاب'),
    ('د خیبر پښتونخوا (KPK) په زراعت کې د جوارو اهمیت څه دی؟', 'جوار په خیبر پښتونخوا کې له غنمو وروسته دوهم لوی فصل دی او د غرنیو سیمو د خلکو اصلي خواړه دي.', 'ولایت: KPK'),
    ('جوار په خیبر پښتونخوا کې چیرته کرل کیږي؟', 'دا د مردان، صوابۍ او پېښور د میداني سیمو نه علاوه د سوات، دیر او هزاره ډویژنونو په غرنیو سیمو کې هم کرل کیږي.', 'ولایت: KPK'),
    ('د خیبر پښتونخوا په غرنیو سیمو کې جوار کله کرل کیږي؟', 'په غرنیو سیمو کې کښت د اپریل څخه تر می پورې ترسره کیږي او حاصلات په سپتمبر او اکتوبر کې ترسره کیږي.', 'ولایت: KPK'),
    ('ولې د KPK کروندګر مجبور دي چې د هایبرډونو پرځای عام ډولونه وکري؟', 'په لیرې پرتو سیمو کې ګرانو هایبرډ تخمونو او سرې ته د نه لاسرسي له امله، کروندګر د اعظم او بابر په څیر عام ډولونه کاروي.', 'ولایت: KPK'),
    ('په سندهـ کې جوار په لویه کچه کرل کیږي؟', 'د پنجاب او KPK په پرتله، سند کم جوار تولیدوي، په عمده توګه د سخت تودوخې او د اوبو کمښت له امله.', 'ولایت: سند'),
    ('په سندهـ کې د جوارو د کرلو وخت څه دی؟', 'په سند کې، د بهاري فصل د جنوري په وروستیو یا فبروري کې کرل کیږي، پداسې حال کې چې د خریف فصل په جولای کې کرل کیږي.', 'ولایت: سند'),
    ('په سند کې د جوارو لویه ګټه څه ده؟', 'په سندهـ کې د جوارو لویه برخه د سوداګریزو غلو پر ځای د څارویو لپاره د شنو واښو په توګه کرل کیږي.', 'ولایت: سند'),
    ('جوار په بلوچستان کې چیرته کرل کیږي؟', 'په بلوچستان کې، دا په محدوده پیمانه د نصیر آباد په څیر په میدانونو او ځینو غرنیو دره کې کرل کیږي.', 'ولایت: بلوچستان'),
    ('په بلوچستان کې د جوارو په کښت کې تر ټولو لوی خنډ څه دی؟', 'جوار ډیرې اوبه ته اړتیا لري، په داسې حال کې چې د بلوچستان ډیری سیمې د اوبو له سخت کمښت او وچکالۍ سره مخ دي.', 'ولایت: بلوچستان'),
    ('د هایبرډ جوارو لپاره د سرې عمومي سپارښتنه څه ده؟', 'هایبرډ جوار ډیری تغذیه ته اړتیا لري. دوه بوجۍ DAP، له 3 څخه تر 4 بوجۍ یوریا او له 1 څخه تر 2 بوجۍ پوتاش په هر جریبه کې اړتیا لري.', 'د سرې مدیریت'),
    ('کله فاسفورس (DAP) او پوټاش باید اضافه شي؟', 'دا غوره ده چې د DAP او پوتاش بشپړه اندازه د کرنې په وخت کې د خاورې چمتو کولو په وخت کې تطبیق کړئ.', 'د سرې مدیریت'),
    ('نایتروجن (یوریا) باید په جوار کې څنګه وکارول شي؟', 'یوریا باید په قسطونو کې وکارول شي: لومړی قسط د 4-5 پاڼو په مرحله کې، دویم د زنګون په لوړوالي کې او وروستی قسط د کرلو څخه مخکې.', 'د سرې مدیریت'),
    ("ولې په جوارو کې 'پورته جامې' مهم دي؟", 'د نبات د ودې په مهمو پړاوونو کې د یوریا کارول قد ته وده ورکوي او د پوزې اندازه زیاتوي.', 'د سرې مدیریت'),
    ('د جوارو په حاصلاتو کې د زنک رول څه دی؟', 'جوار د زنک کمښت سره ډیر حساس دی. د زنک اضافه کول د غنمو ډکول ښه کوي او د سپینې جواني ناروغۍ مخه نیسي.', 'د سرې مدیریت'),
    ('که جوار پوتاش ورنکړل شي څه به کیږي؟', 'د پوتاش پرته، ډډونه ضعیف دي، کیدای شي حاصلات راټیټ شي او پوډر ممکن دانه تولید نکړي.', 'د سرې مدیریت'),
    ('سخته تودوخه څنګه د جوارو ګرده اغیزه کوي؟', 'که چیرې د پوزې د جوړیدو په وخت کې د تودوخې درجه له 38-40 درجو څخه لوړه شي، ګرده مړه کیږي او پوزه خالي پریږدي.', 'د سرې مدیریت'),
    ('د جوارو ټول فصل څومره اوبو ته اړتیا لري؟', 'د فصل او خاورې ډول پورې اړه لري، جوار له 8 څخه تر 12 لیټرو اوبو ته اړتیا لري.', 'اوبولګولو او زیان رسوونکو واښو'),
    ('د اوبو لګولو لپاره خورا مهم ګامونه کوم دي؟', 'د پوستکي کولو او دانه کولو مرحله ترټولو مهمه ده. په دې وخت کې د اوبو کمښت په تولید کې د جدي کمښت لامل کیږي.', 'اوبولګولو او زیان رسوونکو واښو'),
    ("د جوار د 'کالر روټ' څخه څنګه ساتنه وکړو؟", 'تل د ډډونو په مینځ کې اوبه واچوئ او اجازه مه ورکوئ چې د ډډونو څخه پورته لاړ شي ترڅو د ډډ اساس وچ پاتې شي.', 'اوبولګولو او زیان رسوونکو واښو'),
    ('د جوارو په کرونده کې عام زیان رسونکي واښه څه دي؟', 'زیان رسونکي واښه، واښه او واښه د جوارو دښمنان دي.', 'اوبولګولو او زیان رسوونکو واښو'),
    ('د زیان رسوونکو واښو د له منځه وړلو لپاره کوم زهرونه (Herbicides) کارول کیږي؟', 'د کښت څخه د 24 ساعتونو په اوږدو کې د اټرازین + میتولاکلور سپری کول د زیان رسوونکو واښو مخنیوی کوي.', 'اوبولګولو او زیان رسوونکو واښو'),
    ('آیا واښه وژونکي په ولاړ فصل کې سپری کیدی شي؟', 'هو، د نبات د 3 څخه تر 4 پاڼی مرحله کې، مخدره توکي لکه نیکوسلفوران سپری کیدی شي.', 'اوبولګولو او زیان رسوونکو واښو'),
    ('ولې د فال آرمی ورم (FAW) د جوارو لپاره خطرناک دی؟', "دا یو ویجاړونکی حشره ده چې د نبات په 'ورل' کې ناست وي او هغه خوري او ټول فصل په چټکۍ سره ویجاړوي.", 'د آفتونو مدیریت'),
